mapper.select:
select #{name} as finprodName, ti.A1, ti.B1, ti.A2, ti.B2, ti.B3, ti.FREE_36FILE, ti.FREE_46FILE, ti.FREE_70FILE, ti.FREE_SEC, ti.C1, ti.C2, ti.C3, ti.C4, ti.C5, ti.E1, ti.E2, ti.E3 from TAX_DECLARE_SUM_INFO ti left join BOK_BOOKSET bb on bb.bookset_id = ti.SUBJECT_NATURE
left join FIN_PRODUCT fp on fp.finprod_id = bb.ACCT_SUBJECT_ID where 1=1
and DATE_FORMAT(ti.DECLARE_YEAR,'%Y') = #{declarYear}
and ti.DECLARE_DATE = #{declarDate}
and ti.DECLARE_TYPE = #{sumDimen}
